<div class="filter-card card"><form method="get"><input type="hidden" name="page" value="projects"><div class="filter-grid"><input aria-label="Cari project" name="search" placeholder="Search project..." value="<?=e($filters['search'])?>"><select aria-label="Filter status project" name="status"><option value="">All status</option><?php foreach(['Planning','Active','Completed','Archived'] as $s):?><option <?=($filters['status']===$s?'selected':'')?> value="<?=$s?>"><?=$s?></option><?php endforeach;?></select><button class="btn btn-primary">Search</button><a class="btn" href="?page=projects">Reset</a></div></form></div>
<div class="page-actions"><p class="muted">Project dan status sesuai alur final project.</p><?php if($currentUser['role']==='Admin'):?><a class="btn btn-primary" href="?page=projects&action=create">+ Add Project</a><?php endif;?></div>
<div class="card"><div class="table-wrap"><table><thead><tr><th>Project</th><th>Status</th><th>Start</th><th>Target</th><th>Tasks</th><th>Action</th></tr></thead><tbody><?php foreach($result['items'] as $p):?><tr><td><strong><?=e($p['name'])?></strong><div class="muted small"><?=e(mb_strimwidth($p['description'],0,70,'...'))?></div></td><td><span class="badge status-<?=strtolower($p['status'])?>"><?=e($p['status'])?></span></td><td><?=e($p['start_date'])?></td><td><?=e($p['target_date'])?></td><td><?=number_format($p['task_count'])?></td><td class="actions"><a class="btn btn-sm" href="?page=projects&action=view&id=<?=$p['id']?>">View</a><?php if($currentUser['role']==='Admin'):?><a class="btn btn-sm" href="?page=projects&action=edit&id=<?=$p['id']?>">Edit</a><?php if($p['task_count']>0 && $p['status']!=='Archived'):?><form method="post" action="?page=projects&action=archive&id=<?=$p['id']?>" onsubmit="return confirm('Archive project ini?')"><?=$csrfField?><button class="btn btn-sm">Archive</button></form><?php endif;?><?php endif;?></td></tr><?php endforeach;?><?php if(!$result['items']):?><tr><td colspan="6" class="empty">Tidak ada project yang sesuai filter.</td></tr><?php endif;?></tbody></table></div><?=paginationLinks($result,['page'=>'projects','search'=>$filters['search'],'status'=>$filters['status']])?></div>
